# -*- coding: utf-8 -*-
"""Сделка уходит в Оценку через её же бота — других каналов с точки нет.

Порт Postgres Оценки закрыт наружу, своего сервера мы больше не держим, значит
приложение на точке не может ни писать в её базу, ни читать из неё. Зато у точки есть
интернет, а у бота — база под рукой. Поэтому:

  1. Приложение складывает сделку в JSON и отправляет файлом в рабочую группу Telegram
     (`sendDocument` токеном бота). К файлу — читаемая карточка и кнопка.
  2. Оценщик нажимает кнопку. Нажатие — единственное, что приносит боту эту посылку:
     входящие сообщения бот видит, свои исходящие — нет, а в `callback_query` Telegram
     отдаёт сообщение целиком, вместе с файлом.
  3. Обработчик бота читает файл, добавляет видео и фото, принятые по тому же коду,
     и создаёт сделку (deploy/оценка_бот/).

Нажатие заодно и подтверждение: оценщик видит в карточке ровно то, что уйдёт в сделку.
Токена бота в приложении достаточно только для отправки — читать чужие чаты им нельзя,
`getUpdates` мы не трогаем (он занят самим ботом).
"""
from __future__ import annotations

import json
import logging

log = logging.getLogger("pintel.ocenka.tg")

API = "https://api.telegram.org"
КНОПКА = "Создать сделку в Оценке"
ПРЕФИКС_КНОПКИ = "kiosk_deal_"
ПРЕДЕЛ_ПОДПИСИ = 1024                 # подпись к файлу в Telegram — не больше 1024 знаков


class ОшибкаОтправки(RuntimeError):
    """Человеческий текст, почему посылка не ушла."""


def _деньги(сумма, валюта="₸") -> str:
    if сумма in (None, ""):
        return "не указана"
    return f"{int(сумма):,}".replace(",", " ") + f" {валюта}"


def карточка(п: dict, валюта: str = "₸") -> str:
    """Читаемая карточка к файлу: по ней оценщик решает, нажимать ли кнопку.

    Показываем ровно то, что уйдёт в сделку, — иначе подтверждение ничего не стоит.
    """
    сд = п.get("сделка") or {}
    кл = п.get("клиент") or {}
    шапка = "🧾 Оценка · код " + str(п.get("код") or "—")
    строки = [шапка + (f" · {п['точка']}" if п.get("точка") else "")]
    голова = " · ".join(str(x) for x in (
        сд.get("model"), f"{сд.get('ddr')} ГБ" if сд.get("ddr") else None, сд.get("color")) if x)
    if голова:
        строки.append(голова)
    имеи = [x for x in (п.get("imei") or []) if x]
    if имеи:
        строки.append("IMEI " + " · ".join(имеи))
    if сд.get("akb"):                                # «86-90 (86%)» — как в её карточке
        строки.append("Аккумулятор " + str(сд["akb"])
                      + (f" ({сд['akb_exact']}%)" if сд.get("akb_exact") else ""))
    if сд.get("phone_status"):
        строки.append("Детали: " + str(сд["phone_status"]))
    else:
        строки.append("Детали: Apple не подтвердила — решает оценщик")
    for замок in (п.get("замки") or []):
        строки.append("⚠ " + str(замок))
    строки.append("Цена клиенту: " + _деньги(сд.get("price_grade_auto"), валюта))
    комплект = ", ".join(x for x, есть in (("коробка", сд.get("box")), ("шнур", сд.get("cord"))) if есть)
    строки.append(f"SIM: {сд.get('sim') or '—'} · комплект: {комплект or 'без коробки и шнура'}")
    строки.append("Клиент: " + " · ".join(str(x) for x in (кл.get("имя"), кл.get("телефон")) if x))
    if сд.get("comment"):
        строки.append("Комментарий: " + str(сд["comment"]))
    строки.append("")
    строки.append("Нажмите кнопку — бот создаст сделку и подставит видео и фото, "
                  "присланные по этому коду. Оценщиком станет тот, кто их присылал.")
    текст = "\n".join(строки)
    if len(текст) > ПРЕДЕЛ_ПОДПИСИ:                 # Telegram обрежет сам — лучше по-человечески
        текст = текст[:ПРЕДЕЛ_ПОДПИСИ - 1].rsplit("\n", 1)[0] + "\n…"
    return текст


def клавиатура(код: str) -> dict:
    return {"inline_keyboard": [[{"text": КНОПКА, "callback_data": ПРЕФИКС_КНОПКИ + str(код)}]]}


def отправить(токен: str, чат, посылка: dict, валюта: str = "₸", таймаут: float = 30.0) -> dict:
    """Отправить сделку в чат. → {message_id, чат}. Ошибку Telegram отдаём словами."""
    import httpx
    if not токен:
        raise ОшибкаОтправки("в kiosk.toml не задан ocenka_bot_token — отправлять нечем")
    if not чат:
        raise ОшибкаОтправки("в kiosk.toml не задан ocenka_chat_id — отправлять некуда")
    код = str(посылка.get("код") or "")
    файл = json.dumps(посылка, ensure_ascii=False, indent=1).encode("utf-8")
    try:
        r = httpx.post(
            f"{API}/bot{токен}/sendDocument",
            data={"chat_id": str(чат), "caption": карточка(посылка, валюта),
                  "reply_markup": json.dumps(клавиатура(код))},
            files={"document": (f"ocenka_{код or 'deal'}.json", файл, "application/json")},
            timeout=таймаут)
        ответ = r.json()
    except Exception as exc:                                     # noqa: BLE001
        raise ОшибкаОтправки(f"Telegram не ответил: {exc}") from None
    if not ответ.get("ok"):
        raise ОшибкаОтправки("Telegram отказал: " + str(ответ.get("description") or ответ))
    res = ответ.get("result") or {}
    log.info("ocenka: посылка %s ушла в чат %s (сообщение %s)", код, чат, res.get("message_id"))
    return {"message_id": res.get("message_id"), "чат": чат, "код": код}
